def split_top_level(s):
    out, buf, depth = [], [], 0
    for ch in s:
        if ch in '([':
            depth += 1
            buf.append(ch)
        elif ch in ')]':
            depth = max(0, depth - 1)
            buf.append(ch)
        elif ch == ',' and depth == 0:
            out.append(''.join(buf))
            buf = []
        else:
            buf.append(ch)
    out.append(''.join(buf))
    return [x.strip() for x in out if x.strip()]

def parse_pairs(s):
    out = {}
    i, n = 0, len(s)
    while i < n:
        if s[i] == ';':
            i += 1
            continue
        j = s.find('=', i)
        if j < 0:
            break
        nxt = s.find(';', i)
        if 0 <= nxt < j:
            i = nxt + 1
            continue
        key = s[i:j].strip()
        k = j + 1
        quoted = k < n and s[k] == "'"
        if quoted:
            e = s.find("'", k + 1)
            if e < 0:
                val, i = s[k + 1:], n
            else:
                val = s[k + 1:e]
                i = e + 1
                while i < n and s[i] != ';':
                    i += 1
                i += 1
        else:
            e = s.find(';', k)
            if e < 0:
                val, i = s[k:], n
            else:
                val, i = s[k:e], e + 1
        if key:
            out[key] = val if quoted else val.strip()
    return out

def quote_join(items):
    out = []
    for x in items:
        x = str(x)
        if ',' in x or '"' in x:
            out.append('"' + x.replace('"', '""') + '"')
        else:
            out.append(x)
    return ', '.join(out)

