def base_convert(s, from_base, to_base):
    s = (s or "").strip()
    if not s:
        return ""
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    sign = ""
    if s[0] == "-":
        sign, s = "-", s[1:]
    n = int(s, from_base)
    if n == 0:
        return "0"
    out = ""
    while n > 0:
        out = digits[n % to_base] + out
        n //= to_base
    return sign + out

