class Limiter:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.hits = {}

    def hit(self, key, now):
        ts = [t for t in self.hits.get(key, []) if now - self.window < t <= now]
        if len(ts) < self.limit:
            self.hits.setdefault(key, []).append(now)
            return True
        return False

    def count(self, key, now):
        return len([t for t in self.hits.get(key, []) if now - self.window < t <= now])

